/* GitHub DNA — Primer: familiar dev surfaces, link blue, precise grays, 6px radius */
.theme-github-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.978 0.003 247.9);
  --surface-2: oklch(0.947 0.007 247.9);
  --fg: oklch(0.254 0.011 254.0);
  --fg-muted: oklch(0.495 0.022 250.8);
  --accent: oklch(0.540 0.191 257.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.563 0.207 295.0);
  --line: oklch(0.881 0.013 244.3);
  --success: oklch(0.524 0.140 148.0);
  --warning: oklch(0.554 0.117 75.0);
  --danger: oklch(0.552 0.205 24.5);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Mona Sans", sans-serif;
  --font-body: "Mona Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-github-dna h1,
.theme-github-dna h2,
.theme-github-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-github-dna { --font-ui: var(--font-display); }
.theme-github-dna h1 { font-weight: 600; letter-spacing: -0.02em; }
.theme-github-dna kbd { border-bottom-width: 3px; }

/* alt mode: auto-derived dark variant */
.theme-github-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
